// === Tab: mySketch ===
let h;
let angle = 0;


let speed = 0.01;

function setup() {
  createCanvas(600, 600);
  noStroke();
  background("#005");
  h = height / 2;
}

function draw() {
  for (let y = 0; y < h; y += 6) {
    let c = lerpColor(color("#005"), color("#4BB"), y / h);
    fill(c);
    square(y, y, width - 2 * y);
  }
  fill("#fff");
  for (let i = 6000; i > 0; i--) {
    let x = h + sin(i + angle) * sin(i * i) * 250;
    let y = h + 250 * cos(i * i);
    circle(x, y, 2);
  }
  angle += speed; 
}

